    for x in [x for x in r['records'] if x['cat']=='entail_verify'][:4]: print('  VER',x['text'][:50],'||',repr(x['out'][:40]))
    for x in [x for x in r['records'] if x['cat']=='inverse']: print('  INV',x['text'][:50],'||',repr(x['out'][:40]))
    n=0
    for x,y in zip(r['records'],b['records']):
        if x['cat']=='loc_counterfact' and y['correct'] and not x['correct'] and n<4: print('  CF',x['text'][:50],'||',repr(x['out'][:50]),'| base',repr(y['out'][:30])); n+=1
EOF

